export default function IntersessionPreview() {
  const images = [
    { src: 'https://images.unsplash.com/photo-1579820010410-c10411aaaa88?auto=format&fit=crop&q=80&w=800', alt: 'Drone field application' },
    { src: 'https://images.unsplash.com/photo-1451187580459-43490279c0fa?auto=format&fit=crop&q=80&w=800', alt: 'Global satellite view' },
    { src: 'https://images.unsplash.com/photo-1541888086425-d81bb19240f5?auto=format&fit=crop&q=80&w=800', alt: 'Surveying instrument' },
    { src: 'https://images.unsplash.com/photo-1534081333815-ae501905494a?auto=format&fit=crop&q=80&w=800', alt: 'Topographic map' },
  ];

  return (
    <section id="intersession" className="section-padding bg-base-100">
      <div className="container-standard">
        <div className="flex flex-col md:flex-row justify-between items-end mb-16 gap-6">
          <div className="max-w-2xl space-y-4">
            <h2 className="text-sm font-semibold text-primary uppercase tracking-widest">Ongoing Work</h2>
            <h3 className="text-4xl md:text-5xl font-bold tracking-tight">Intersession Glimpses</h3>
            <p className="text-base-content/70 mt-4 max-w-lg leading-relaxed text-lg">
              Behind the scenes of our continual global research deployment and field operations between main events.
            </p>
          </div>
          <a href="#gallery" className="btn btn-outline border-base-300 rounded-btn text-base-content hover:bg-base-200 hover:border-base-300 font-medium hidden md:inline-flex">
            View 2026 Full Gallery &rarr;
          </a>
        </div>
        
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 md:gap-6">
          {images.map((img, i) => (
            <div key={i} className="relative aspect-[4/5] w-full overflow-hidden rounded-box group border border-base-300/50 bg-base-200">
              <img 
                src={img.src} 
                alt={img.alt} 
                className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-105" 
                loading="lazy"
              />
              <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300 flex items-end p-6">
                <span className="text-white font-medium text-sm tracking-wide">{img.alt}</span>
              </div>
            </div>
          ))}
        </div>
        
        <div className="mt-8 md:hidden text-center">
          <a href="#gallery" className="btn btn-primary rounded-btn w-full text-primary-content">
            View 2026 Full Gallery
          </a>
        </div>
      </div>
    </section>
  );
}
